    "จากการระบาดของโรคใบร่วงชนิดใหม่ของยางพาราซึ่งเริ่มต้นในประเทศอินโดนีเซียเมื่อ พ.ศ. ๒๕๕๙โดยแสดงลักษณะอาการของแผลกลมขนาดใหญ่บนใบ และก่อให้เกิดการร่วงของใบอย่างรุนแรง ซึ่งไม่เคยมีรายงานอาการเช่นนี้ในยางพารามาก่อน โรคดังกล่าวสามารถแพร่กระจายได้อย่างรวดเร็วภายในเวลาเพียง ๗ปี และได้ลุกลามไปยังอีก ๙ ประเทศในทวีปเอเชีย ได้แก่ อินโดนีเซีย อินเดีย ศรีลังกา มาเลเซีย ไทย กัมพูชาเวียดนาม ฟิลิปปินส์ และเมียนมาร์ สำหรับประเทศไทย พบการระบาดครั้งแรกใน พ.ศ. ๒๕๖๒ ในพื้นที่ภาคใต้๑๐ จังหวัด ยกเว้นภูเก็ต ระนอง ชุมพร และนครศรีธรรมราช โดยพบมากในพื้นที่ปลูกยางที่สูงและบริเวณเชิงเขา รวมถึงฝั่งทะเลอันดามันและจังหวัดชายแดนภาคใต้ โรคนี้ส่งผลกระทบอย่างมีนัยสำคัญต่อการเจริญเติบโตและผลผลิตน้ำยางของต้นยางพารา ทั้งนี้ เนื่องจากเป็นโรคชนิดใหม่ จึงมีความจำเป็นต้องศึกษาข้อมูลพื้นฐานในหลายด้าน อาทิ เชื้อสาเหตุ สภาพการระบาด ประสิทธิภาพของสารเคมีในการควบคุมโรค และการประเมินระดับความต้านทานของพันธุ์ยางที่แนะนำ รวมถึงพืชอาศัยชนิดอื่น ๆ เพื่อพัฒนาเทคโนโลยีการควบคุมโรคอย่างยั่งยืน โดยผลการศึกษาแสดงให้เห็นว่า เชื้อสาเหตุคือ Colletotrichum siamense ซึ่งได้รับการพิสูจน์โดยวิธี Koch’s Postulates และการวิเคราะห์อณูวิทยา การทดสอบสารเคมีเบื้องต้น ได้แก่ ไดฟิโนโคนาโซลโพรพิโคนาโซล และคาร์เบนดาซิม พบว่ามีประสิทธิภาพดีในการควบคุมโรค โดยให้ผลสอดคล้องทั้งในสภาพห้องปฏิบัติการและในแปลงทดลอง ด้านการประเมินความต้านทานของพันธุ์ยาง ได้แก่ GT 1, BPM 24, PB 235, RRIM 612, PB 311 และ RRIT 3801 พบว่ามีแนวโน้มต้านทานต่อโรคได้ดีทั้งในเรือนทดลองและในสภาพแวดล้อมธรรมชาติ แม้การปลูกเชื้อในห้องปฏิบัติการมักมีความแปรปรวนสูง ซึ่งจำเป็นต้องทำการทดสอบซ้ำหลายครั้งเพื่อเพิ่มความเชื่อมั่นในผลวิเคราะห์"
