    "อย่างไรก็ตาม ประเทศไทยยังไม่ได้กำหนดปริมาณแคลเซียมสูงสุดต่อวันซึ่งไม่ก่อผลเสียในคนทั่วไปที่สุขภาพดีไว้อย่างเป็นทางการ แต่หากอ้างอิงจากงานวิจัยปัจจุบันมีคำแนะนำว่า ผู้ใหญ่อายุ ๑๙–๕๐ ปี ไม่ควรบริโภคเกิน ๒,๕๐๐ มิลลิกรัมต่อวัน หากอายุมากกว่า ๕๐ ปี ไม่ควรเกิน ๒,๐๐๐ มิลลิกรัมต่อวัน เนื่องจากการทำงานของไตซึ่งทำหน้าที่ขับแคลเซียมส่วนเกินทำงานลดลงตามอายุ แต่ร่างกายก็มีกลไกป้องกันเมื่อบริโภคแคลเซียมปริมาณมาก จึงไม่ต้องกังวลมากจนเกินไปว่าจะได้รับพิษจากแคลเซียม นอกจากนี้ทุกคนควรออกกำลังกายสม่ำเสมอ และลดปัจจัยเสี่ยงต่าง ๆ (เช่น งดการสูบบุหรี่) เพื่อให้กระดูกแข็งแรงตั้งแต่เด็กจนสูงวัย"
